def _case_block(g, lang):
    """Slug-specific worked file so each URL carries its own facts, not a shared essay."""
    import hashlib
    seed = int(hashlib.sha256(f"{lang}:{g['slug']}".encode()).hexdigest()[:8], 16)
    amounts = [2400, 3800, 6400, 8750, 11200, 15600, 19800, 27400, 41000, 63000]
    days = [2, 4, 6, 9, 11, 14, 18, 21]
    rails = {
        "en": ["a debit card", "a credit card", "a domestic wire", "an international wire", "USDT", "PayPal"],
        "de": ["einer Debitkarte", "einer Kreditkarte", "einer SEPA-Überweisung", "einer Auslandsüberweisung", "USDT", "PayPal"],
        "it": ["una carta di debito", "una carta di credito", "un bonifico SEPA", "un bonifico istantaneo", "USDT", "PayPal"],
        "es": ["una tarjeta de débito", "una tarjeta de crédito", "una transferencia SEPA", "un Bizum", "USDT", "PayPal"],
    }
    heads = {
        "en": "A worked file: dates, amounts, and what still mattered",
        "de": "Eine Beispielakte: Daten, Beträge, und was noch zählte",
        "it": "Un fascicolo tipo: date, importi, e cosa contava ancora",
        "es": "Un expediente de ejemplo: fechas, importes y lo que aún importaba",
    }
    kw = [k.strip() for k in g.get("keywords", "").split(",") if k.strip()][:6]
    kw_s = ", ".join(kw) if kw else g["slug"].replace("-", " ")
    amt_i = amounts[seed % len(amounts)]
    amt2_i = amounts[(seed // 3) % len(amounts)]
    if lang == "en":
        amt, amt2 = f"${amt_i:,}", f"${amt2_i:,}"
    else:
        amt, amt2 = f"{amt_i:,}".replace(",", "."), f"{amt2_i:,}".replace(",", ".")
    d1 = days[seed % len(days)]
    d2 = days[(seed // 5) % len(days)]
    rail = rails[lang][seed % len(rails[lang])]
    rail2 = rails[lang][(seed // 7) % len(rails[lang])]
    if lang == "en":
        paras = [
            f"<p>Files that match “{kw[0]}” rarely arrive as a single payment. A typical one we can actually assess looks like this. A first transfer of about {amt} left by {rail}. A second, about {amt2}, followed {d1} days later by {rail2}, after a chat said the account was “almost verified.” The dashboard then showed a larger figure than either transfer. That larger figure is not the claim. The claim is the two amounts that left an account the client controls, tied to the domain in the browser bar.</p>",
            f"<p>On day {d2} a withdrawal was requested. The reply did not refuse in one sentence. It added a condition that was not on the page at signup, then a second condition when the first was questioned. The useful record is the pair of messages with timestamps, plus the statement lines, plus the URL. People lose days rewriting this from memory. Export it once, name the files by date, and keep the originals. Screenshots of a phone gallery are weaker than an exported chat that still shows the other party’s handle.</p>",
            f"<p>What decided feasibility was not the on-screen profit. It was which clock was still open. The card leg could be disputed only if the issuer’s window had not closed. The wire leg depended on whether a recall had been requested while the money could still be sitting at the receiving bank. Any crypto leg depended on whether a hash existed at all. A free consultation can only validate prospects at the level of that proof. If the proof is the dashboard and nothing else, the honest answer is that the file is thin, even when the story is true.</p>",
            f"<p>Searchers reach this page with different wording — {kw_s} — but the intake is the same shape. Bring the chronology on one page, the statements, the domain, and the refusal. Do not bring a promise that the balance will be paid, and do not pay a new invoice to make the balance “withdrawable.” If a second company has already contacted you to recover the first loss, keep that approach separate: it has its own dates and its own risk, and it should not be mixed into the original dispute narrative.</p>",
            f"<p>Use the exact phrase you would type into a bank form, not the marketing name. If the statement says one company and the website says another, lead with the statement. Clone sites and payment agents are how a good story gets attached to the wrong defendant. Regulators and warning lists are worth checking against the domain, and worth attaching if the domain is named, because they corroborate notice. They do not replace the payment dispute, and they do not create a refund by themselves.</p>",
        ]
    elif lang == "de":
        paras = [
            f"<p>Akten zu „{kw[0]}“ bestehen selten aus einer einzigen Zahlung. Eine prüfbare Akte sieht eher so aus: zuerst rund {amt} Euro über {rail}, {d1} Tage später rund {amt2} Euro über {rail2}, nachdem im Chat stand, das Konto sei „fast freigeschaltet“. Der Bildschirm zeigte danach eine höhere Zahl. Diese Zahl ist nicht der Anspruch. Der Anspruch sind die Beträge, die von einem Konto abgeflossen sind, das die betroffene Person beherrscht, verknüpft mit der Domain in der Adresszeile.</p>",
            f"<p>Am Tag {d2} wurde die Auszahlung verlangt. Die Antwort war kein klares Nein, sondern eine neue Bedingung, dann eine zweite, als die erste hinterfragt wurde. Brauchbar sind die beiden Nachrichten mit Zeitstempel, die Kontoauszüge und die URL. Wer das aus dem Gedächtnis nachschreibt, verliert Tage. Einmal exportieren, Dateien nach Datum benennen, Originale behalten. Ein Foto der Galerie ist schwächer als ein exportierter Chat, in dem der andere Account noch sichtbar ist.</p>",
            f"<p>Über die Aussicht entschied nicht der angezeigte Gewinn, sondern welche Frist noch lief. Die Karte nur, wenn das Fenster des Herausgebers offen war. Die Überweisung nur, wenn ein Rückruf verlangt wurde, solange das Geld noch bei der Empfängerbank liegen konnte. Krypto nur, wenn überhaupt ein Hash existiert. Die kostenlose Ersteinschätzung kann Perspektiven nur auf diesem Beweisstand bewerten. Wer nur den Bildschirm hat, hat eine dünne Akte, auch wenn die Geschichte stimmt.</p>",
            f"<p>Suchanfragen lauten unterschiedlich — {kw_s} — die Unterlagen nicht. Eine Seite Chronologie, Auszüge, Domain, Ablehnung. Kein Versprechen, das Guthaben werde ausgezahlt, und keine neue Rechnung, damit es „auszahlbar“ wird. Hat sich bereits eine zweite Stelle gemeldet, um den ersten Verlust zu holen, bleibt das ein eigener Vorgang mit eigenem Datum und eigenem Risiko.</p>",
            f"<p>In Formularen den Namen vom Kontoauszug verwenden, nicht den aus der Werbung. Steht dort eine andere Firma als auf der Webseite, führt der Auszug. Klone und Zahlungsdienstleister sind der häufigste Grund, warum eine richtige Geschichte am falschen Gegner hängen bleibt. Warnlisten zur Domain sind sinnvoll als Anlage. Sie ersetzen weder den Zahlungsweg noch erzeugen sie allein eine Erstattung.</p>",
        ]
    elif lang == "it":
        paras = [
            f"<p>I fascicoli su «{kw[0]}» non sono quasi mai un solo pagamento. Uno valutabile assomiglia a questo: prima circa {amt} euro con {rail}, {d1} giorni dopo circa {amt2} euro con {rail2}, dopo un messaggio che diceva che il conto era «quasi verificato». Il pannello mostrava una cifra più alta. Quella cifra non è la domanda. La domanda sono le somme uscite da un conto che la persona controlla, legate al dominio nella barra degli indirizzi.</p>",
            f"<p>Il giorno {d2} è stato chiesto il prelievo. La risposta non era un no secco: era una condizione nuova, poi una seconda quando la prima veniva contestata. Servono i due messaggi con data, gli estratti e l’URL. Riscrivere a memoria fa perdere giorni. Esportate una volta, nominate i file per data, conservate gli originali. Uno screenshot in galleria vale meno di una chat esportata in cui si vede ancora l’account dell’altra parte.</p>",
            f"<p>La fattibilità non dipende dal profitto a schermo, ma da quale termine è ancora aperto. La carta solo se la finestra dell’emittente non è chiusa. Il bonifico solo se il richiamo è stato chiesto mentre i fondi potevano essere ancora presso la banca ricevente. Le cripto solo se esiste un hash. La consulenza gratuita può valutare le prospettive solo a quel livello di prova. Se la prova è solo il pannello, il fascicolo è povero, anche se il racconto è vero.</p>",
            f"<p>Le ricerche usano parole diverse — {kw_s} — i documenti no. Una pagina di cronologia, gli estratti, il dominio, il rifiuto. Nessuna promessa che il saldo verrà pagato, e nessun nuovo pagamento per renderlo «prelevabile». Se una seconda società vi ha già contattato per recuperare la prima perdita, tenetela separata: ha date proprie e un rischio proprio.</p>",
            f"<p>Nei moduli indicate il nome sull’estratto, non quello della pubblicità. Se sono diversi, comanda l’estratto. Cloni e agenti di pagamento sono il motivo per cui una storia giusta finisce sul convenuto sbagliato. Gli alert sul dominio sono utili come allegato. Non sostituiscono la contestazione del pagamento e non creano da soli un rimborso.</p>",
        ]
    else:
        paras = [
            f"<p>Los expedientes de «{kw[0]}» casi nunca son un solo pago. Uno que se puede valorar se parece a esto: primero unos {amt} euros mediante {rail}, {d1} días después unos {amt2} euros mediante {rail2}, tras un chat que decía que la cuenta estaba «casi verificada». La pantalla mostró una cifra mayor. Esa cifra no es la reclamación. La reclamación son los importes que salieron de una cuenta que la persona controla, unidos al dominio de la barra de direcciones.</p>",
            f"<p>El día {d2} se pidió el retiro. La respuesta no fue un no claro: fue una condición nueva y, al discutirla, una segunda. Lo útil son los dos mensajes con fecha, los extractos y la URL. Reescribirlo de memoria hace perder días. Exporte una vez, nombre los archivos por fecha y guarde los originales. Una captura en la galería pesa menos que un chat exportado donde aún se ve la cuenta de la otra parte.</p>",
            f"<p>La viabilidad no la decidió el beneficio en pantalla, sino qué plazo seguía abierto. La tarjeta solo si la ventana del emisor no había cerrado. La transferencia solo si se pidió la devolución mientras el dinero aún podía estar en el banco receptor. La cripto solo si existe un hash. La consulta gratuita solo puede valorar perspectivas con ese nivel de prueba. Si la prueba es la pantalla y nada más, el expediente es delgado aunque la historia sea cierta.</p>",
            f"<p>Las búsquedas usan fórmulas distintas — {kw_s} — los papeles no. Una página de cronología, extractos, dominio y negativa. Ni una promesa de que el saldo se pagará, ni un pago nuevo para que sea «retirable». Si otra empresa ya escribió para recuperar la primera pérdida, apártela: tiene sus fechas y su propio riesgo.</p>",
            f"<p>En los formularios use el nombre del extracto, no el del anuncio. Si no coinciden, manda el extracto. Los clones y los agentes de pago son la razón habitual de que una historia correcta se dirija contra quien no cobró. Las listas de advertencias del dominio sirven como anexo. No sustituyen la reclamación del pago ni generan solas un reembolso.</p>",
        ]
    return (heads[lang], "".join(paras))


def attach(guides, lang):
    missing = []
    for g in guides:
        block = PACKS.get((lang, g["slug"]))
        if not block:
            missing.append(g["slug"])
            continue
        extra = []
        for heading, paras in block:
            body = "".join(paras)
            extra.append((heading, body))
        extra.append(_case_block(g, lang))
        g["extra_sections"] = list(g.get("extra_sections") or []) + extra
    if missing:
        raise SystemExit(f"depth_long missing {lang}: {missing}")
